#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, b;
    cin >> n >> b;
    vector<int> a(n + 1);
    vector<int> oddPrefix(n + 1, 0);
    vector<int> evenPrefix(n + 1, 0);

    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        if (a[i] % 2 == 1) {
            oddPrefix[i] = oddPrefix[i - 1] + 1;
            evenPrefix[i] = evenPrefix[i - 1];
        } else {
            oddPrefix[i] = oddPrefix[i - 1];
            evenPrefix[i] = evenPrefix[i - 1] + 1;
        }
    }

    int totalCuts = 0;
    int sizeDifferences = n / 2 - 1;
    vector<int> differences(sizeDifferences);
    for (int i = 2; i < n; i += 2) {
        if (oddPrefix[i] == evenPrefix[i]) {
            differences[i / 2 - 1] = abs(a[i] - a[i + 1]);
        } else {
            differences[i / 2 - 1] = -1;
        }
    }

    sort(differences.begin(), differences.end());

    long long currentSum = 0;
    for (int diff : differences) {
        if (diff != -1 && currentSum + diff <= b) {
            totalCuts++;
            currentSum += diff;
        }
    }

    cout << totalCuts << "\n";

    return 0;
}

